const pages=JSON.parse(new TextDecoder().decode(Bun.gunzipSync(Uint8Array.from(atob(""),c=>c.charCodeAt(0)))));
function handle(req){const url=new URL(req.url);const path=url.pathname;const headers=new Headers({"X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin"}); if(url.hostname!=="corp.casa")headers.set("X-Robots-Tag","noindex"); if(req.method!=="GET" && req.method!=="HEAD"){headers.set("Allow","GET, HEAD");return new Response("Method not allowed",{status:405,headers})}const regular=path.replace(/index\.html$/,""); if(!Object.hasOwn(pages,path)&& (regular!==path && Object.hasOwn(pages,regular) || Object.hasOwn(pages,path+"/"))){headers.set("Location", "https://corp.casa"+(regular!==path?regular:path+"/")+url.search);return new Response(null,{status:308,headers})}if(path==="/healthz")return new Response(req.method==="HEAD"?null:"ok",{headers});if(!Object.hasOwn(pages,path))return new Response(req.method==="HEAD"?null:"Página não encontrada",{status:404,headers});headers.set("Content-Type",path.endsWith(".jpg")?"image/jpeg":path.endsWith(".xml")?"application/xml; charset=utf-8":path.endsWith(".txt")?"text/plain; charset=utf-8":path.endsWith(".css")?"text/css; charset=utf-8":"text/html; charset=utf-8");headers.set("Cache-Control","public, max-age=300");return new Response(req.method==="HEAD"?null:path.endsWith(".jpg")?Uint8Array.from(atob(pages[path]),c=>c.charCodeAt(0)):pages[path],{headers});}
Bun.serve({hostname:"0.0.0.0",port:Number(Bun.env.PORT||3000),fetch:handle});
